def solve(g):
    H,W=len(g),len(g[0])
    from collections import Counter,deque
    bg=Counter(x for row in g for x in row).most_common(1)[0][0]
    seen=[[False]*W for _ in range(H)]; out=[row[:] for row in g]
    objs=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and not seen[i][j]:
                col=g[i][j]; q=deque([(i,j)]); cells=[]
                while q:
                    a,b=q.popleft()
                    if 0<=a<H and 0<=b<W and not seen[a][b] and g[a][b]==col:
                        seen[a][b]=True; cells.append((a,b))
                        q+= [(a+1,b),(a-1,b),(a,b+1),(a,b-1)]
                objs.append((col,cells))
    singles=[]
    for c,s in objs:
        if len(s)==1: singles.append((c,s[0]))
    for c,cs in objs:
        if len(cs)>1:
            center=(sum(a for a,_ in cs)/len(cs), sum(b for _,b in cs)/len(cs))
            cand=min(singles,key=lambda p:(abs(p[1][0]-center[0])+abs(p[1][1]-center[1]),p[0],p[1]))
